node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import fs from 'node:fs';
import crypto from 'node:crypto';
import {execFileSync} from 'node:child_process';
const agp='d8305fcdda94613c116e6530af44458336d9d4ee';
const pin='e705b3d749400d0a79efe98e5338e9c84a1695b8';
const owner='ecb2f5f29d6aba8c58e9588d34b677b516ef03d8';
const root='/home/apnex/taceng/context-lab';
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const git=(cwd,...args)=>execFileSync('git',['-C',cwd,...args],{maxBuffer:32<<20});
assert.equal(git(process.cwd(),'rev-parse','HEAD').toString().trim(),agp);
const paths=['README.md','VISION.md','docs/ARCHITECTURE-TARGET.md','docs/BACKLOG.md','docs/BOARD.md','docs/DELTAS/DELTA-1.md','docs/DELTAS/DELTA-2.md','docs/DELTAS/DELTA-3.md','packages/core/src/index.ts','packages/core/src/adapters.ts','packages/core/src/outcome.ts','packages/core/src/runtime-sandbox.ts','packages/core/src/run-conductor.ts'];
const sources=[];
for(const revision of [pin,owner])for(const file of paths){
 const exists=execFileSync('git',['-C',root,'ls-tree','--name-only',revision,'--',file],{encoding:'utf8'}).trim();
 if(!exists){sources.push({revision,file,present:false});continue;}
 const bytes=git(root,'show',revision+':'+file);
 sources.push({revision,file,bytes:bytes.length,sha256:sha(bytes),blob:git(root,'rev-parse',revision+':'+file).toString().trim()});
}
const records=['docs/reviews/admission-diagnostic-proposal.md','docs/reviews/admission-diagnostic-amendment-01.md','docs/reviews/admission-diagnostic-source-findings.md','docs/reviews/admission-diagnostic-design-recheck-02.txt','docs/reviews/admission-evaluator-qualification/admission-qualification-profile.json','docs/reviews/admission-evaluator-qualification/admission-qualification-review-01.txt','docs/reviews/admission-lifetime-assurance-r4/admission-provider-config.json','docs/reviews/admission-lifetime-assurance-r4/admission-execution-config.json','docs/reviews/admission-lifetime-assurance-r4/admission-provider-readiness-06.txt','docs/reviews/admission-lifetime-assurance-r4/admission-gate-review-01.txt','docs/reviews/admission-lifetime-assurance-r4/records/2026-10-16-060526-admission-clarity/run.json'];
const evidence=records.map(file=>{const bytes=fs.readFileSync(file);assert.deepEqual(bytes,git(process.cwd(),'show',agp+':'+file));return{file,bytes:bytes.length,sha256:sha(bytes)};});
const run=JSON.parse(fs.readFileSync(records.at(-1)));
const projection={file:records.at(-1),method:run.method,runtimes:run.runtimes,recordedRouteIds:Object.keys(run.routes??{}),readerProfiles:run.probes.map(({arm,member,pass,reasons})=>({arm,member,pass,reasonCount:reasons.length})),judgeProfiles:run.judgeProbes.map(({arm,member,pass,reasons})=>({arm,member,pass,reasonCount:reasons.length})),snapshotPopulation:run.snapshot.population.map(({id,runtime,model,family,settings})=>({id,runtime,model,family,settings:settings??null}))};
assert.equal(projection.readerProfiles.length,6);assert.equal(projection.judgeProfiles.length,3);
assert.ok([...projection.readerProfiles,...projection.judgeProfiles].every(p=>p.pass&&p.reasonCount===0));
const before=['docs/BOARD.md','docs/VERIFICATION.md'].map(file=>{const bytes=fs.readFileSync(file);return{file,sha256:sha(bytes),bytes:bytes.length,boardRows:file.endsWith('BOARD.md')?bytes.toString().split('\n').filter(l=>l.startsWith('|')&&l.includes('`B53`')):undefined};});
console.log(JSON.stringify({agpAtInspection:agp,qualifiedEvaluator:pin,ownerCommittedDocsAtInspection:owner,sources,evidence,retainedRunProjection:projection,beforeReconciliation:before,claimBoundary:'File/Git identity and existing record metadata only. No invocation, credential/account read, capability enforcement or fresh isolation measurement.'},null,2));
NODE

