node --input-type=module > /tmp/agp-admission-capability.HT7H1f/static-output-01.txt 2>&1 <<'NODE'
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {execFileSync} from 'node:child_process';
const record=JSON.parse(fs.readFileSync('docs/reviews/admission-diagnostic-capability-checks.json'));
const evidence=record.priorInputs;
const root=process.cwd();
const upstream='/home/apnex/taceng/context-lab';
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const git=(cwd,...args)=>execFileSync('git',['-C',cwd,...args],{maxBuffer:32<<20});
assert.equal(git(root,'rev-parse','HEAD').toString().trim(),evidence.agpAtInspection);
assert.equal(record.diagnosticInvocations,0);
assert.equal(record.providerRequestsMadeByInventory,0);
for(const source of evidence.sources){
 const spec=source.revision+':'+source.file;
 if(source.present===false){
  assert.equal(git(upstream,'ls-tree','--name-only',source.revision,'--',source.file).length,0);
 }else{
  const bytes=git(upstream,'show',spec);
  assert.equal(bytes.length,source.bytes);
  assert.equal(sha(bytes),source.sha256);
  assert.equal(git(upstream,'rev-parse',spec).toString().trim(),source.blob);
 }
}
for(const entry of evidence.evidence){
 const bytes=fs.readFileSync(entry.file);
 assert.equal(bytes.length,entry.bytes);
 assert.equal(sha(bytes),entry.sha256);
 assert.deepEqual(bytes,git(root,'show',evidence.agpAtInspection+':'+entry.file));
}
assert.equal(git(root,'diff','--exit-code',evidence.agpAtInspection,'--','docs/reviews','packages','cli','rustcli','schemas').length,0);
const run=JSON.parse(fs.readFileSync(evidence.retainedRunProjection.file));
assert.equal(run.method.revision,'6e6d0a92965a15ec473c661887b2b9c5037fedcf');
assert.notEqual(run.method.revision,evidence.qualifiedEvaluator);
assert.equal(Object.hasOwn(run,'routes'),false);
assert.equal(run.probes.length,6);
assert.equal(run.judgeProbes.length,3);
assert.ok([...run.probes,...run.judgeProbes].every(p=>p.pass===true&&p.reasons.length===0));
const profile=JSON.parse(fs.readFileSync('docs/reviews/admission-evaluator-qualification/admission-qualification-profile.json'));
assert.equal(profile.evaluatorAdoptedForLiveUse,false);
const docs=['docs/reviews/admission-diagnostic-capability-findings.md','docs/reviews/admission-diagnostic-capability-result.md'];
const links=[];
const headingSlug=s=>s.toLowerCase().replace(/[\x60*_]/g,'').replace(/[^\p{L}\p{N}\s-]/gu,'').trim().replace(/\s/g,'-');
for(const file of docs){
 const contents=fs.readFileSync(file,'utf8');
 for(const match of contents.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){
  const target=match[1];
  if(target.startsWith('https:')){
   const m=/^https:\/\/github\.com\/apnex\/context-lab\/blob\/([0-9a-f]{40})\/([^#]+)(?:#.*)?$/.exec(target);
   assert.ok(m,target);
   git(upstream,'cat-file','-e',m[1]+':'+m[2]);
   links.push({file,target,checked:'pinned local Git object; no remote freshness claim'});
  }else{
   const [name,anchor]=target.split('#');
   const destination=path.resolve(path.dirname(file),name||path.basename(file));
   assert.ok(fs.existsSync(destination),target);
   if(anchor){
    const headings=fs.readFileSync(destination,'utf8').split('\n').filter(l=>/^#{1,6} /.test(l)).map(l=>headingSlug(l.replace(/^#{1,6} /,'')));
    assert.ok(headings.includes(anchor),target);
   }
   links.push({file,target,checked:'local file and anchor where supplied'});
  }
 }
}
const board=fs.readFileSync('docs/BOARD.md','utf8');
const beforeBoard=evidence.beforeReconciliation.find(e=>e.file==='docs/BOARD.md');
const afterRows=board.split('\n').filter(l=>l.startsWith('|')&&l.includes('\x60B53\x60'));
assert.equal(afterRows.length,beforeBoard.boardRows.length);
assert.equal(afterRows[0],beforeBoard.boardRows[0]);
assert.equal(afterRows.at(-1),beforeBoard.boardRows.at(-1));
let reversed=board;
const replaceOnce=(s,from,to)=>{
 assert.equal(s.split(from).length,2);
 return s.replace(from,to);
};
for(let i=1;i<afterRows.length-1;i++)reversed=replaceOnce(reversed,afterRows[i],beforeBoard.boardRows[i]);
const newParagraph=[
'The director selected that read-only inventory; the [completed stage 0a result](reviews/admission-diagnostic-capability-result.md) is a terminal zero-call stop, not a diagnostic FAIL or readiness PASS.\\',
'The [pinned source inventory](reviews/admission-diagnostic-capability-findings.md) identifies missing supported request/spend, trace and retention evidence, while retaining the old isolation/delivery acceptance within its original scope.\\',
'Actual deployed provider/account capabilities remain unknown; the next recommendation is approval for a bounded owner request, not packet construction or an AGP-local evaluator project.\\'
].join('\n');
const oldParagraph='The next recommendation is only a read-only inventory of existing supported capabilities and accepted evidence; unknown prerequisites end that attempt with an owner and revival trigger, not an AGP-local evaluator project.\\';
reversed=replaceOnce(reversed,newParagraph,oldParagraph);
assert.equal(sha(reversed),beforeBoard.sha256);
assert.equal(Buffer.byteLength(reversed),beforeBoard.bytes);
assert.ok(!board.includes("Do we select the amended diagnostic's zero-call capability inventory"));
for(const item of ['B53','B56']){
 const line=board.split('\n').find(l=>l.startsWith('| \x60'+item+'\x60 |')&&l.includes(' | \x60I'));
 assert.ok(line?.endsWith('| open |'),item);
}
const verification=fs.readFileSync('docs/VERIFICATION.md','utf8');
const start=verification.indexOf('### 4.45 Admission diagnostic capability inventory and zero-call stop\n');
const end=verification.indexOf('## 5. Modular test architecture\n');
assert.ok(start>0&&end>start);
const previousVerification=verification.slice(0,start)+verification.slice(end);
const beforeVerification=evidence.beforeReconciliation.find(e=>e.file==='docs/VERIFICATION.md');
assert.equal(sha(previousVerification),beforeVerification.sha256);
assert.equal(Buffer.byteLength(previousVerification),beforeVerification.bytes);
const documents=[...docs,'docs/BOARD.md','docs/VERIFICATION.md'].map(file=>{
 const bytes=fs.readFileSync(file);
 return{file,sha256:sha(bytes),bytes:bytes.length};
});
console.log(JSON.stringify({
 disposition:'PASS - author static identities, links and record preservation only',
 sourceIdentitiesChecked:evidence.sources.length,
 frozenEvidenceFilesChecked:evidence.evidence.length,
 untouchedTrackedAreas:['docs/reviews','packages','cli','rustcli','schemas'],
 oldProfiles:{readers:6,judges:3,acceptedAtOldScopeOnly:true},
 links,documents,
 board:{beforeSha256:beforeBoard.sha256,afterSha256:sha(board),beforeRows:beforeBoard.boardRows,afterRows,onlyDeclaredChanges:true,scoresStatusOrderPreserved:true},
 verification:{beforeSha256:beforeVerification.sha256,afterSha256:sha(verification),onlyAppendedSection:true},
 limits:'No runtime capability, deployment, isolation or independent readiness tested.'
},null,2));
